{
  "story": "Why doesn’t a recursive call erase its caller? Start a countdown and follow its calls down to the base case. Then step through the returns and watch which saved input becomes current again.",
  "aha": {
    "stateId": "nested-resumes",
    "observation": "A return pops only the newest frame; the waiting caller resumes with its saved input and return location."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "call-rail",
      "kind": "step-rail",
      "presentation": "Place the story and instructions above the experiment, followed by this rail. Keep all progress and trace on the rail. Brief parameter-control budget: zero; navigation and reset are separate. Reference captures show nested-resumes.",
      "bind": {
        "active": "inputs.step",
        "items": "variant.states"
      }
    },
    {
      "id": "stack-picture",
      "kind": "fixed-picture",
      "presentation": "Program: countdown(n) returns immediately at zero; otherwise it calls countdown(n − 1), then returns. Assume nonnegative integers, synchronous execution, and no tail-call optimization. The initial Current input readout fixes the starting argument; it cannot be edited. Arrange fixed slots vertically: Outer frame below Nested frame below Base frame. Highlighted slots contain live frames; unhighlighted slots are empty placeholders. The callout identifies the executing frame, or the emptied slot after completion. Other highlighted frames are waiting. Preserve label space and readable text at native width.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "executing-frame",
      "kind": "active-callout",
      "presentation": "Anchor beside the bound slot without covering the stack. Identify the action and its reason; keep numerical values in the readout.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "stack-readouts",
      "kind": "value-readout",
      "presentation": "Place below the picture. Current input is the executing frame’s local argument, expressed as an exact unitless integer without rounding. An em dash means no frame is executing. Render Status as the bound status line.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "items": "variant.states",
      "label": "Call-stack state",
      "presentation": "Use Previous and Next, retaining those names when disabled at boundaries. Default: first state; increment: one state; bounds: first through last state. Each action changes the live stack or resumes a saved caller. Every state, including nested-resumes, persists until the learner acts. Provide accessible button names, visible focus, and keyboard activation."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and all defaults. Provide the accessible name Reset, visible focus, and keyboard activation."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Recursive countdown",
        "regions": [
          {
            "id": "outer",
            "label": "Outer frame",
            "values": [
              "Stores its own input and return location."
            ]
          },
          {
            "id": "nested",
            "label": "Nested frame",
            "values": [
              "Stores its own input and return location."
            ]
          },
          {
            "id": "base",
            "label": "Base frame",
            "values": [
              "Stores its own input and return location."
            ]
          }
        ],
        "links": [],
        "states": [
          {
            "id": "outer-starts",
            "label": "Outer frame starts",
            "short": "Outer",
            "sentence": "The Outer frame begins executing.",
            "why": "Its input is positive, so it will make a recursive call.",
            "active": [
              "outer"
            ],
            "calloutRegion": "outer",
            "readouts": [
              {
                "id": "current-input",
                "label": "Current input",
                "value": "2"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Outer frame running."
              }
            ]
          },
          {
            "id": "nested-starts",
            "label": "Nested frame starts",
            "short": "Nested",
            "sentence": "The Nested frame is pushed above the waiting Outer frame.",
            "why": "The recursive call gets a separate local input; the Outer frame keeps its saved input.",
            "active": [
              "outer",
              "nested"
            ],
            "calloutRegion": "nested",
            "readouts": [
              {
                "id": "current-input",
                "label": "Current input",
                "value": "1"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Nested frame running; Outer frame waiting."
              }
            ]
          },
          {
            "id": "base-starts",
            "label": "Base frame starts",
            "short": "Base",
            "sentence": "The Base frame is pushed above the waiting callers.",
            "why": "Its input meets the base case, so it returns without making another call.",
            "active": [
              "outer",
              "nested",
              "base"
            ],
            "calloutRegion": "base",
            "readouts": [
              {
                "id": "current-input",
                "label": "Current input",
                "value": "0"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Base frame running; Nested frame and Outer frame waiting."
              }
            ]
          },
          {
            "id": "nested-resumes",
            "label": "Nested frame resumes",
            "short": "Resume nested",
            "sentence": "The Base frame is popped; the Nested frame resumes.",
            "why": "The Nested frame kept its input and the location immediately after its recursive call.",
            "active": [
              "outer",
              "nested"
            ],
            "calloutRegion": "nested",
            "readouts": [
              {
                "id": "current-input",
                "label": "Current input",
                "value": "1"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Nested frame resumed; Outer frame still waiting."
              }
            ]
          },
          {
            "id": "outer-resumes",
            "label": "Outer frame resumes",
            "short": "Resume outer",
            "sentence": "The Nested frame is popped; the Outer frame resumes.",
            "why": "The Outer frame continues immediately after its recursive call, using its unchanged local input.",
            "active": [
              "outer"
            ],
            "calloutRegion": "outer",
            "readouts": [
              {
                "id": "current-input",
                "label": "Current input",
                "value": "2"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Outer frame resumed."
              }
            ]
          },
          {
            "id": "complete",
            "label": "Outer frame returns",
            "short": "Complete",
            "sentence": "The Outer frame returns, leaving these stack slots empty.",
            "why": "Every recursive frame has returned in reverse creation order; execution continues outside this countdown.",
            "active": [],
            "calloutRegion": "outer",
            "readouts": [
              {
                "id": "current-input",
                "label": "Current input",
                "value": "—"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Countdown complete; all displayed frames popped."
              }
            ]
          }
        ]
      }
    ]
  }
}
